// Complete normal-mode mechanics plus translated pinned MSVC physics.
// Binary stdout is game-digest-v1, independently generated by game_oracle.cpp.
#include "../../clone/cuda/world.cuh"
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <iterator>
#include <memory>
#include <stdexcept>
#include <string>
#include <vector>
#ifdef __CUDACC__
#include <cuda_runtime.h>
#endif
namespace game=irisu::cuda_game;
using Frame=irisu::game_digest::Frame;

static std::FILE* body_dump{};
static unsigned clone_at=~0U;
static bool clone_verified{};
GAME_HD void trajectory(game::World& world,const std::uint32_t* words,unsigned steps,Frame* frames) {
#ifndef __CUDA_ARCH__
  std::unique_ptr<game::World> clone;
  std::vector<unsigned char> clone_memory;
#endif
  frames[0]=world.frame();
#ifndef __CUDA_ARCH__
  if(body_dump)for(const auto& b:world.simulator.bodies_)irisu::game_digest::dump_body(body_dump,0,b);
#endif
  for(unsigned i=0;i<steps&&!world.failed();++i) {
    const auto result=world.step(game::replay_action(words[i],i));
    frames[i+1]=world.frame(result);
#ifndef __CUDA_ARCH__
    if(body_dump)for(const auto& b:world.simulator.bodies_)irisu::game_digest::dump_body(body_dump,world.simulator.tick_,b);
    if(clone) {
      const auto cloned_result=clone->step(game::replay_action(words[i],i));
      const auto cloned_frame=clone->frame(cloned_result);
      if(std::memcmp(&cloned_frame,&frames[i+1],sizeof(Frame)) || clone->state_hash()!=world.state_hash())
        throw std::runtime_error("cloned full state diverged");
    }
    if(i+1==clone_at) {
      clone=std::make_unique<game::World>();
      clone_memory.assign(world.guest.memory,world.guest.memory+world.guest.capacity);
      std::memcpy(clone.get(),&world,sizeof(game::World));
      clone->bind(clone_memory.data());
      if(clone->state_hash(true)!=world.state_hash(true))throw std::runtime_error("clone/rebind state mismatch");
    }
#endif
  }
#ifndef __CUDA_ARCH__
  if(clone) {
    if(clone->state_hash(true)!=world.state_hash(true))throw std::runtime_error("clone arena suffix mismatch");
    clone_verified=true;
  }
#endif
}
#ifdef __CUDACC__
__global__ void run(game::World* world,unsigned char* memory,unsigned capacity,
 const unsigned char* image,unsigned image_size,unsigned seed,const std::uint32_t* words,unsigned steps,Frame* frames) {
  if(threadIdx.x||blockIdx.x)return;
  ::new(static_cast<void*>(world)) game::World();
  world->initialize(memory,capacity,image,image_size,seed);
  trajectory(*world,words,steps,frames);
}
void check(cudaError_t code) {
  if(code!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(code));
}
#endif
std::vector<unsigned char> read(const char* name) {
  std::ifstream f(name,std::ios::binary);
  if(!f)throw std::runtime_error(std::string("cannot read ")+name);
  return {(std::istreambuf_iterator<char>(f)),{}};
}
unsigned word(const std::vector<unsigned char>& bytes,std::size_t at) {
  return bytes[at]|(unsigned(bytes[at+1])<<8)|(unsigned(bytes[at+2])<<16)|(unsigned(bytes[at+3])<<24);
}
int main(int argc,char** argv) {
 try {
  if(argc<3)throw std::runtime_error("usage: game-probe guest-image.bin replay.rpy [steps] [--gpu] [--arena-mib N] [--seed N] [--clone-at N]");
  const auto image=read(argv[1]),replay=read(argv[2]);
  if(image.empty()||image.size()>0x20000||replay.size()<56||(replay.size()-52)%4||word(replay,16)!=0)throw std::runtime_error("invalid image/replay");
  unsigned steps=(replay.size()-52)/4,capacity=8*1024*1024,seed=word(replay,0);bool gpu=false;
  for(int i=3;i<argc;++i){std::string a=argv[i];if(a=="--gpu")gpu=true;
    else if(a=="--arena-mib"&&i+1<argc)capacity=std::stoul(argv[++i])*1024*1024;
    else if(a=="--seed"&&i+1<argc)seed=std::stoul(argv[++i]);
    else if(a=="--clone-at"&&i+1<argc)clone_at=std::stoul(argv[++i]);else steps=std::stoul(a);}
  if(gpu&&clone_at!=~0U)throw std::runtime_error("clone-at requires host probe");
  if(steps>(replay.size()-52)/4||capacity<0x40000||capacity>512*1024*1024)throw std::runtime_error("invalid steps/capacity");
  std::vector<std::uint32_t> words(steps);for(unsigned i=0;i<steps;++i)words[i]=word(replay,52+4*i);
  std::vector<Frame> frames(steps+1);
  auto world=std::make_unique<game::World>();
  const auto begin=std::chrono::steady_clock::now();double kernel_ms=0;
#ifdef __CUDACC__
  if(gpu){
    game::World* device_world{};unsigned char *memory{},*device_image{};std::uint32_t* device_words{};Frame* device_frames{};
    check(cudaDeviceSetLimit(cudaLimitStackSize,128*1024));
    check(cudaMalloc(&device_world,sizeof(game::World)));check(cudaMalloc(&memory,capacity));
    check(cudaMalloc(&device_image,image.size()));check(cudaMemcpy(device_image,image.data(),image.size(),cudaMemcpyHostToDevice));
    check(cudaMalloc(&device_words,words.size()*4));check(cudaMemcpy(device_words,words.data(),words.size()*4,cudaMemcpyHostToDevice));
    check(cudaMalloc(&device_frames,frames.size()*sizeof(Frame)));check(cudaMemset(device_frames,0,frames.size()*sizeof(Frame)));
    cudaEvent_t start{},stop{};check(cudaEventCreate(&start));check(cudaEventCreate(&stop));check(cudaEventRecord(start));
    run<<<1,1>>>(device_world,memory,capacity,device_image,image.size(),seed,device_words,steps,device_frames);
    check(cudaGetLastError());check(cudaEventRecord(stop));check(cudaEventSynchronize(stop));
    float ms{};check(cudaEventElapsedTime(&ms,start,stop));kernel_ms=ms;
    check(cudaMemcpy(world.get(),device_world,sizeof(game::World),cudaMemcpyDeviceToHost));
    check(cudaMemcpy(frames.data(),device_frames,frames.size()*sizeof(Frame),cudaMemcpyDeviceToHost));
    check(cudaFree(device_frames));check(cudaFree(device_words));check(cudaFree(device_image));check(cudaFree(memory));check(cudaFree(device_world));
    check(cudaEventDestroy(start));check(cudaEventDestroy(stop));
  }else
#else
  if(gpu)throw std::runtime_error("CUDA was not compiled in");
#endif
  {
    const std::uint16_t cw=0x027f;__asm__ __volatile__("fldcw %0"::"m"(cw));
    auto* dump=std::getenv("IRISU_GAME_BODY_DUMP_FILE");
    body_dump=dump?std::fopen(dump,"w"):nullptr;
    if(dump&&!body_dump)throw std::runtime_error("cannot open body dump");
    std::vector<unsigned char> memory(capacity);
    world->initialize(memory.data(),capacity,image.data(),image.size(),seed);
    trajectory(*world,words.data(),steps,frames.data());
    if(body_dump)std::fclose(body_dump);body_dump=nullptr;
  }
  if(clone_at!=~0U && (gpu||!clone_verified))throw std::runtime_error("clone gate requires host and 0<clone-at<=steps");
  const auto& sim=world->simulator;
  std::fprintf(stderr,"{\"backend\":\"%s\",\"experimental\":true,\"clone_verified\":%s,\"rows\":%u,\"requested_steps\":%u,\"tick\":%llu,\"guest_error\":%u,\"fault_pc\":%u,\"guest_heap\":%u,\"game_failed\":%s,\"config_hash\":%llu,\"score\":%lld,\"canonical_score\":%lld,\"level\":%u,\"chain\":%u,\"kernel_ms\":%.6f,\"elapsed_seconds\":%.9f,\"world_bytes\":%zu,\"arena_bytes\":%u}\n",
     gpu?"cuda-translated-full-game":"host-translated-full-game",clone_verified?"true":"false",steps+1,steps,(unsigned long long)sim.tick_,world->guest.error,world->guest.fault_pc,world->guest.heap,
     sim.failed_?"true":"false",(unsigned long long)sim.config_hash(),(long long)sim.score_,(long long)sim.latest_final_score_,sim.level_,sim.highest_chain_,kernel_ms,
     std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count(),sizeof(game::World),capacity);
  // Device pointer bindings are invalid on host after download. Check only the
  // copied scalar failure state; do not dereference simulator.physics_.guest_.
  if(world->guest.error||sim.failed_||sim.bodies_.overflow||sim.groups_.overflow||sim.active_contact_pairs_.overflow)return 1;
  for(const auto& frame:frames){const auto* p=reinterpret_cast<const unsigned char*>(&frame);unsigned char data[96];
   for(unsigned i=0;i<12;++i){std::uint64_t value{};std::memcpy(&value,p+8*i,8);for(unsigned j=0;j<8;++j)data[8*i+j]=value>>(8*j);}
   if(std::fwrite(data,96,1,stdout)!=1)throw std::runtime_error("write failed");}
  return std::fflush(stdout)==0?0:1;
 }catch(const std::exception& e){std::fprintf(stderr,"game-probe: %s\n",e.what());return 1;}
}
